	"gorm.io/gorm"
	"gorm.io/gorm/clause"
	"gorm.io/gorm/schema"
)

type GenericRepository[T schema.Tabler] struct {
	db    *gorm.DB
	model T
}

func NewGenericeRepoPointr[T schema.Tabler](db *gorm.DB, model T) *GenericRepository[T] {
	return &GenericRepository[T]{
		db:    db,
		model: model,
	}
}

func (repo GenericRepository[T]) FindOneByIDSelection(
	ctx context.Context,
	entity interface{},
	id interface{},
) error {
	selection, err := repo.extractSelection(entity)
	if err != nil {
		return err
	}

	return repo.db.WithContext(ctx).
		Table(repo.model.TableName()).
		Select(selection).
		First(entity, "id = ?", id).Error
}

var (
	Search = func(val string, col ...string) clause.Expression {
		var exps = make([]clause.Expression, len(col))
		for i, c := range col {
			tableName, colName := getColNameStr(c)
			exps[i] = clause.Like{
				Column: clause.Column{Name: colName, Table: tableName},
				Value:  "%" + val + "%",
			}
		}
		return clause.Or(exps...)
	}

	Equal = func(val interface{}, col string) clause.Expression {
		tableName, colName := getColNameStr(col)
		return clause.Eq{
			Column: clause.Column{Name: colName, Table: tableName},
			Value:  val,
		}
	}
)

package db

import (
	"gorm.io/gorm"
)

type BaseRepository interface {
	SetupConnection(db *gorm.DB)
}

type DBTransaction struct {
	db    *gorm.DB
	repos []BaseRepository
}

func NewDBTransaction(db *gorm.DB, repos ...BaseRepository) DBTransaction {
	result := DBTransaction{
		db:    db,
		repos: make([]BaseRepository, 0),
	}
	for _, repo := range repos {
		result.repos = append(result.repos, repo)
	}
	return result
}

func (main *DBTransaction) Begin() {
	tx := main.db.Begin()
	for _, rp := range main.repos {
		rp.SetupConnection(tx)
	}
	main.db = tx
}

func (main *DBTransaction) End(err error) error {
	if err != nil {
		if errTrx := main.db.Rollback().Error; errTrx != nil {
			return errTrx
		}
		return nil
	}
	return main.db.Commit().Error
}

package localerror

import (
	"base-be-golang/pkg/logger"
	"errors"
	"gorm.io/gorm"
)

type InvalidDataError struct {
	Msg             string
	DataToTemplated map[string]string
}

func (e InvalidDataError) Error() string { return e.Msg }

type AccessControlError struct {
	Msg string
}

func (e AccessControlError) Error() string { return e.Msg }

func IsInvalidData(err error) bool {
	return err != nil && errors.As(err, &InvalidDataError{})
}

func IsAccessNotAllowedUserNotFound(err error) bool {
	return err != nil && errors.Is(err, AccessControlError{Msg: "SessionExpired"})
}

package payload

type ResponseMeta struct {
	Success      bool   `json:"success"`
	MessageTitle string `json:"messageTitle"`
	Message      string `json:"message"`
	ErrorServer  string `json:"errorServer,omitempty"`
}

type ErrorResponse struct {
	ResponseMeta
	Data   any `json:"data"`
	Errors any `json:"errors,omitempty"`
}

func DefaultDataInvalidResponse(validationErrors any) *ErrorResponse {
	return &ErrorResponse{
		ResponseMeta: ResponseMeta{
			MessageTitle: "Oops, something went wrong.",
			Message:      "Data invalid.",
		},
		Errors: validationErrors,
	}
}

package api

import (
	"base-be-golang/pkg/cache"
	"base-be-golang/pkg/logger"
	"base-be-golang/pkg/miniostorage"
	"os"
	"github.com/gin-gonic/gin"
	"gorm.io/gorm"
)

type Router interface {
	Route(handler *gin.RouterGroup)
}

type Api struct {
	server   *gin.Engine
	db       *gorm.DB
	cache    cache.DbClient
	minioStr miniostorage.StorageMinio
	reZero   *logger.ReZero
	routers  []Router
}

func (a *Api) Start() error {
	root := a.server.Group("/api/v1")
	for _, router := range a.routers {
		router.Route(root)
	}
	port := os.Getenv("APP_PORT")
	return a.server.Run("0.0.0.0:" + port)
}
